actions.script:
const found = ec.service.sync().name('org.moqui.devaide.ArtifactServices.search#Artifacts')
    .parameters({text: String(term || ''), kinds: 'entity,view-entity', limit: 20}).call() || {}
const options = (found.artifacts || []).map((row) => ({value: row.name, label: row.name}))
const asked = String(term || '')
ec.message.clearErrors()
ec.web.sendJsonResponse(asked && !options.some((option) => option.value === asked) && asked.indexOf('.') > 0
    ? [{value: asked, label: asked}].concat(options) : options)

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const entity = guided.entityContext(artifact)
const ops = entity.ops.entity
const merged = entity.entity ? ops.mergeFields(entity.entity.fields || [], entity.element, entity.edit && entity.edit.inPlace)
    .find((field) => field.name === fieldName) : null
if (!merged) ec.message.addError('No field ' + fieldName)
else {
    // only what changed, so an upstream field gets an override of just that
    const built = guided.entityEdit(entity, (element) => {
        let list = []
        const change = (attribute, now, was) => { if (String(now || '') !== String(was || '')) list = list.concat(ops.setFieldAttribute(element, fieldName, attribute, now)) }
        change('type', fieldType, merged.type)
        // the key is the defining file's: an extension (which shows no Primary key) leaves it as it is
        if (entity.edit && entity.edit.inPlace) change('is-pk', isPk === 'true' ? 'true' : '', merged.isPk ? 'true' : '')
        change('not-null', notNull === 'true' ? 'true' : '', merged.notNull ? 'true' : '')
        change('default', defaultValue, merged.defaultStr)
        const node = element ? ops.childNamed(element, 'field', 'name', fieldName) : null
        const was = node ? ((entity.ops.pure.children(node, ['description'])[0] || {}).text || '') : ''
        if (String(description || '') !== was) list = list.concat(ops.setFieldDescription(element, fieldName, description || ''))
        return list
    })
    if (built.refused) ec.message.addError(built.refused)
    else guided.apply(entity.target, entity.edit, built.ops)
}

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const entity = guided.entityContext(artifact)
const ops = entity.ops.entity
const kind = ops.KINDS.includes(fieldKind) ? fieldKind : 'Text'
let added = null
const built = guided.entityEdit(entity, (element) => {
    added = ops.addFieldSpec(element, entity.entityName, {kind, words: fieldWords, name: fieldName, type: fieldType, after: afterField,
        related: relatedEntity, values: fieldValues, title: fieldTitle, description, isPk: isPk === 'true', notNull: notNull === 'true',
        extension: !(entity.edit && entity.edit.inPlace)})
    return added.name ? added.ops : []
})
if (built.refused) ec.message.addError(built.refused)
else if (added && added.refused) ec.message.addError(added.refused)
else if (!added || !added.name) ec.message.addError(ec.l10n.localize('A field needs a name: say what it holds'))
else if (!/^[a-z][A-Za-z0-9]*$/.test(added.name)) ec.message.addError('A field name is a letter then letters and digits: ' + added.name)
else if (added.seed.length && !entity.seed) ec.message.addError(ec.l10n.localize('No site component to write the seed data in: create one on Home'))
else {
    guided.apply(entity.target, entity.edit, built.ops)
    // a Picklist's or Status's records, in the site's seed data file, loaded after Save
    if (added.seed.length && !ec.message.hasError()) guided.apply(entity.target, entity.seed, ops.insertRecords((entity.seedFile || {}).outline, added.seed), true)
}

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const entity = guided.entityContext(artifact)
const built = guided.entityEdit(entity, (element) => entity.ops.entity.removeField(element, fieldName))
if (built.refused) ec.message.addError(built.refused)
else if (!built.ops.length) ec.message.addError('The field ' + fieldName + ' is not written in ' + (entity.edit ? entity.edit.path : 'the edit target') + ': an upstream field is removed upstream')
else guided.apply(entity.target, entity.edit, built.ops)

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const entity = guided.entityContext(artifact)
const built = guided.entityEdit(entity, (element) => entity.ops.entity.stepField(element, fieldName, step === 'up' ? -1 : 1))
if (built.refused) ec.message.addError(built.refused)
else guided.apply(entity.target, entity.edit, built.ops)

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const entity = guided.entityContext(artifact)
if (!relatedEntity) ec.message.addError(ec.l10n.localize('Name the related entity'))
else {
    const built = guided.entityEdit(entity, (element) => entity.ops.entity.addRelationship(element, {type: relationshipType || 'one', related: relatedEntity,
        title: relationshipTitle, keyMaps: keyField ? [{fieldName: keyField, related: relatedField}] : []}))
    if (built.refused) ec.message.addError(built.refused)
    else guided.apply(entity.target, entity.edit, built.ops)
}

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const entity = guided.entityContext(artifact)
const built = guided.entityEdit(entity, (element) => entity.ops.entity.removeRelationship(element, relatedEntity, relationshipTitle))
if (built.refused) ec.message.addError(built.refused)
else if (!built.ops.length) ec.message.addError(ec.l10n.localize('The relationship is not written in the edit target: an upstream one is removed upstream'))
else guided.apply(entity.target, entity.edit, built.ops)

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const entity = guided.entityContext(artifact)
const fields = String(indexFields || '').split(/[\s,]+/).filter((name) => name)
if (!indexName || !fields.length) ec.message.addError(ec.l10n.localize('An index needs a name and its fields'))
else {
    const built = guided.entityEdit(entity, (element) => entity.ops.entity.addIndex(element, {name: indexName, unique: unique === 'true', fields}))
    if (built.refused) ec.message.addError(built.refused)
    else guided.apply(entity.target, entity.edit, built.ops)
}

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const entity = guided.entityContext(artifact)
const built = guided.entityEdit(entity, (element) => entity.ops.entity.removeIndex(element, indexName))
if (built.refused) ec.message.addError(built.refused)
else if (!built.ops.length) ec.message.addError(ec.l10n.localize('The index is not written in the edit target: an upstream one is removed upstream'))
else guided.apply(entity.target, entity.edit, built.ops)

const entityName = String(artifact || '').replace(/^(entity|view-entity):/, '')
const out = ec.service.sync().name('org.moqui.devaide.EntityServices.plan#EntityDdl')
    .parameters({entityName, action: ddlAction, fieldName: fieldName || '', columnName: columnName || ''}).call() || {}
if (!ec.message.hasError()) ec.web.sessionAttributes['DevAideGuided.ddl.' + entityName] = JSON.stringify({action: ddlAction,
    fieldName: fieldName || '', columnName: columnName || '', statements: out.statements || [], table: out.tableName})

const entityName = String(artifact || '').replace(/^(entity|view-entity):/, '')
const out = ec.service.sync().name('org.moqui.devaide.EntityServices.run#EntityDdl').parameters({entityName, action: ddlAction,
    fieldName: fieldName || '', columnName: columnName || '', confirmTable: confirmTable || ''}).call() || {}
if (!ec.message.hasError()) {
    ec.web.sessionAttributes.remove('DevAideGuided.ddl.' + entityName)
    ec.message.addMessage('Ran ' + (out.ran || []).length + ' statements', 'success')
}

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const entity = guided.entityContext(artifact)
const ops = entity.ops.entity
const found = ops.recordAt(ops.recordTables((entity.seedFile || {}).outline), seedPath)
const extra = String(seedAttrName || '').trim()
if (!found || found.table.entity !== seedEntity) ec.message.addError(ec.l10n.localize('That record is not in the seed file as staged: open Seed data again'))
else if (extra && !/^[A-Za-z_][A-Za-z0-9_]*$/.test(extra)) ec.message.addError('An attribute name is letters, digits and _: ' + extra)
else {
    const values = {}
    // from the request, where a field emptied is "" (in the context it is null, as a field not given): an empty value
    // removes the attribute, a field not posted stays
    const posted = ec.web.parameters
    for (const name of found.table.columns) {
        const value = posted['seed_' + name]
        if (value !== undefined) values[name] = value == null ? '' : String(value)
    }
    if (extra) values[extra] = String(seedAttrValue || '')
    guided.apply(entity.target, entity.seed, ops.setRecordValues(found.row, values), true)
}

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const entity = guided.entityContext(artifact)
const ops = entity.ops.entity
const outline = (entity.seedFile || {}).outline
const table = ops.recordTables(outline).find((item) => item.entity === seedEntity)
const extra = String(seedAttrName || '').trim()
if (!table) ec.message.addError(ec.l10n.localize('The seed file has no records of that entity as staged: open Seed data again'))
else if (extra && !/^[A-Za-z_][A-Za-z0-9_]*$/.test(extra)) ec.message.addError('An attribute name is letters, digits and _: ' + extra)
else {
    const values = {}
    for (const name of table.columns) { const value = ec.context.get('seed_' + name); if (value != null && String(value) !== '') values[name] = String(value) }
    if (extra && seedAttrValue) values[extra] = String(seedAttrValue)
    const columns = extra && !table.columns.includes(extra) ? table.columns.concat([extra]) : table.columns
    if (!Object.keys(values).length) ec.message.addError(ec.l10n.localize('Give the record a value'))
    else guided.apply(entity.target, entity.seed, ops.addRecord(outline, Object.assign({}, table, {columns}), values), true)
}

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const entity = guided.entityContext(artifact)
const ops = entity.ops.entity
const found = ops.recordAt(ops.recordTables((entity.seedFile || {}).outline), seedPath)
if (!found || found.table.entity !== seedEntity) ec.message.addError(ec.l10n.localize('That record is not in the seed file as staged: open Seed data again'))
else guided.apply(entity.target, entity.seed, [{op: 'remove', at: found.row.path}], true)

const guided = ec.resource.script('component://dev-aide/service/org/moqui/devaide/GuidedEdit.js')
const entity = guided.entityContext(artifact)
const ops = entity.ops.entity
entityName = entity.entityName
view = entity.view
readError = entity.refused || ''
tab = ['fields', 'relationships', 'indexes', 'incoming', 'eeca', 'table', 'seed', 'doc', 'text'].includes(tab) ? tab : 'fields'
definition = entity.entity || {}
const inPlace = !!(entity.edit && entity.edit.inPlace)
// a primary key only where the site defines the entity: on an upstream entity's extension it would change its table's key
editInPlace = inPlace
editFile = entity.editFile || {}
canEdit = !!(view && view.tier !== 'view' && entity.editFile && !entity.editFile.readOnly)
full = !!(view && view.tier === 'full')
editsGo = !view ? '' : !entity.edit ? ec.l10n.localize('This entity is upstream and there is no site component to extend it in: create one on Home')
    : inPlace ? 'Edits go to ' + entity.edit.path : 'Extending in site ' + (entity.edit.component || '') + ': ' + entity.edit.path
readOnlyReason = view && entity.editFile && entity.editFile.readOnly ? entity.editFile.readOnlyReason || '' : ''
pendingText = guided.pendingText(entity.buffer)
bufferExpired = !!entity.buffer.expired
const left = guided.taken(entity.target)
conflict = left.conflict || null
problemRows = (left.problems || []).map((problem) => ({file: problem.file || '', line: problem.line || 0, severity: problem.severity || '', message: problem.message || ''}))
headerText = view ? [definition.isViewEntity ? 'view entity' : 'entity', view.artifact ? view.artifact.component + (view.upstream ? ' (upstream)' : ' (site)') : '',
    'used by ' + (view.usedByCount || 0), (view.extensions || []).length ? (view.extensions || []).length + ' extensions' : ''].filter((part) => part).join(' · ') : ''
workspaceUrl = (view && view.artifact && view.artifact.url) || ''
refsUrl = '/qapps/dev/Artifacts/Refs?artifactId=' + encodeURIComponent('entity:' + entityName)
gridUrl = '/qapps/tools/Data/Grid?entityName=' + encodeURIComponent(entityName)
const tabUrl = (name) => sri.buildUrl('../Edit').addParameters({artifact: 'entity:' + entityName, tab: name}).getUrlWithParams()
const relationships = (definition.relationships || []).filter((rel) => !rel.isAutoReverse)
tabItems = [['fields', 'Fields ' + (definition.fields || []).length], ['relationships', 'Relationships ' + relationships.length],
    ['indexes', 'Indexes'], ['incoming', 'Incoming'], ['eeca', 'EECA rules ' + ((view && view.eecas) || []).length], ['table', 'Table'],
    ['seed', ec.l10n.localize('Seed data')], ['doc', 'Doc'], ['text', 'Text' + (entity.buffer.pending.count ? ' ' + entity.buffer.pending.count : '')]]
    .map(([name, title]) => ({title, url: tabUrl(name), active: name === tab}))

// Fields: the server's with the buffer's element over them, each with where it is defined
const element = entity.element
const origins = {}
for (const field of (view && view.fields) || []) origins[field.name] = field
const own = (name) => !!(element && ops.childNamed(element, 'field', 'name', name))
const ownNames = element ? entity.ops.pure.children(element, ['field']).map((node) => entity.ops.pure.attrOf(node, 'name')) : []
fieldRows = (view ? ops.mergeFields(definition.fields || [], element, inPlace) : []).map((field) => {
    const origin = origins[field.name] || {}
    const node = element ? ops.childNamed(element, 'field', 'name', field.name) : null
    const describedBy = node ? entity.ops.pure.children(node, ['description'])[0] : null
    return {name: field.name, type: field.type || '', kind: ops.kindOf(field, definition.relationships), pk: field.isPk ? 'PK' : '',
        notNull: field.notNull ? 'yes' : '', defaultStr: field.defaultStr || '', description: describedBy ? describedBy.text || '' : '',
        origin: field.unsaved ? 'staged' : (origin.component || '') + (origin.fromExtension ? ' (extension)' : ''),
        pkFlag: field.isPk ? 'true' : '', notNullFlag: field.notNull ? 'true' : '', own: own(field.name),
        first: ownNames[0] === field.name, last: ownNames[ownNames.length - 1] === field.name}
})
fieldTypeOptions = ((view && view.fieldTypes) || []).map((type) => ({type: type.type, label: type.type + (type.sqlType ? ' (' + type.sqlType + ')' : '')}))
kindOptions = ops.KINDS.map((kind) => ({kind}))
afterOptions = fieldRows.map((field) => ({name: field.name}))
// Remove: what uses the field, asked for the one to confirm
removeConfirm = null
if (confirmRemove && fieldRows.some((field) => field.name === confirmRemove)) {
    const used = guided.probe('org.moqui.devaide.ArtifactServices.get#Refs', {artifactId: 'field:' + entityName + '.' + confirmRemove, direction: 'in'})
    const counts = {}
    for (const ref of used.refs || []) { const kind = ref.other ? ref.other.kind : ref.toKind; counts[kind] = (counts[kind] || 0) + 1 }
    const words = Object.keys(counts).map((kind) => counts[kind] + ' ' + kind + (counts[kind] === 1 ? '' : 's'))
    removeConfirm = {name: confirmRemove, text: 'Remove ' + confirmRemove + '? ' + (words.length ? 'It is used in ' + words.join(', ') + '.' : 'Nothing the index knows uses it.')}
}

// Relationships and indexes as the server has them, with the staged element's own after them
const relKey = (rel) => (rel.related || rel.relatedEntityName || '') + '#' + (rel.title || '')
const ownRels = element ? entity.ops.pure.children(element, ['relationship']).map((node) => ({related: entity.ops.pure.attrOf(node, 'related'),
    title: entity.ops.pure.attrOf(node, 'title') || '', type: entity.ops.pure.attrOf(node, 'type') || 'one',
    keys: entity.ops.pure.children(node, ['key-map']).map((key) => entity.ops.pure.attrOf(key, 'field-name') + (entity.ops.pure.attrOf(key, 'related') ? '=' + entity.ops.pure.attrOf(key, 'related') : '')).join(', ')})) : []
const ownRelKeys = new Set(ownRels.map(relKey))
const serverRelKeys = new Set(relationships.map(relKey))
relationshipRows = relationships.map((rel) => ({type: rel.type, related: rel.relatedEntityName, title: rel.title || '',
    keys: Object.entries(rel.keyMap || {}).map(([from, to]) => from + '=' + to).join(', '), own: ownRelKeys.has(relKey(rel)), state: ''}))
    .concat(ownRels.filter((rel) => !serverRelKeys.has(relKey(rel))).map((rel) => Object.assign(rel, {own: true, state: 'staged'})))
const ownIndexes = element ? entity.ops.pure.children(element, ['index']).map((node) => ({name: entity.ops.pure.attrOf(node, 'name'),
    unique: entity.ops.pure.attrOf(node, 'unique') === 'true' ? 'yes' : '',
    fields: entity.ops.pure.children(node, ['index-field']).map((field) => entity.ops.pure.attrOf(field, 'name')).join(', ')})) : []
const ownIndexNames = new Set(ownIndexes.map((index) => index.name))
const serverIndexNames = new Set((definition.indexes || []).map((index) => index.name))
indexRows = (definition.indexes || []).map((index) => ({name: index.name, unique: index.unique ? 'yes' : '', fields: (index.fields || []).join(', '),
    own: ownIndexNames.has(index.name), state: ''}))
    .concat(ownIndexes.filter((index) => !serverIndexNames.has(index.name)).map((index) => Object.assign(index, {own: true, state: 'staged'})))
incomingRows = (definition.relationships || []).filter((rel) => rel.isAutoReverse).map((rel) => ({related: rel.relatedEntityName, type: rel.type,
    title: rel.title || '', keys: Object.entries(rel.keyMap || {}).map(([from, to]) => from + '=' + to).join(', ')}))
eecaRows = ((view && view.eecas) || []).map((rule) => ({name: rule.name || rule.id || '', refType: rule.refType || '',
    place: String(rule.path || '').split('/').slice(-2).join('/') + ':' + (rule.line || 0), url: rule.url ? rule.url + '&view=eca' : ''}))

// the table and its first rows
const table = (view && view.table) || {}
tableNote = definition.isViewEntity ? ec.l10n.localize('A view entity has no table of its own.') : table.error ? table.error : !table.exists ? ec.l10n.localize('No table yet: Save makes it.')
    : !(table.missingColumns || []).length && !(table.extraColumns || []).length ? ec.l10n.localize('The table matches the fields.') : ''
missingColumns = (table.missingColumns || []).join(', ')
extraColumns = (table.extraColumns || []).map((column) => ({column}))
dataRows = ((view && view.data && view.data.rows) || [])
dataColumns = dataRows.length ? Object.keys(dataRows[0]).filter((name) => name !== 'lastUpdatedStamp').slice(0, 8) : []
dataCount = (view && view.data && view.data.count) || 0
// a date-time comes in the rows as the text of its epoch milliseconds: shown in the user's zone, as the Data Grid does
const typeOf = Object.fromEntries((definition.fields || []).map((field) => [field.name, field.type || '']))
dataRows = dataRows.map((row) => Object.fromEntries(Object.entries(row).map(([name, value]) => [name, value == null ? ''
    : typeOf[name] === 'date-time' && /^-?\d+$/.test(String(value)) ? String(ec.l10n.format(String(value), 'yyyy-MM-dd HH:mm:ss')) : String(value)])))
ddlFieldOptions = (definition.fields || []).map((field) => ({name: field.name, label: field.name + ' → ' + ((definition.sqlTypes || {})[field.name] || '')}))
let ddl = null
try { ddl = JSON.parse(ec.web.sessionAttributes['DevAideGuided.ddl.' + entityName] || 'null') } catch (err) { ddl = null }
ddlPlan = ddl
ddlStatements = ddl ? (ddl.statements || []).join(';\n') + ';' : ''

// Seed data: the site's seed file as staged, its records by entity
seedFile = entity.seedFile || null
seedTables = seedFile && seedFile.outline ? ops.recordTables(seedFile.outline) : []
// in the terminal each table is a list with Edit and Remove on each record, and Add row after it
seedNodes = tab === 'seed' ? guided.seedListNodes('entity:' + entityName, seedTables, canEdit,
    (transition, parameters) => sri.buildUrl(transition).addParameters(parameters || {}).getUrlWithParams()) : []

// Doc and Text: the artifact's doc, and the edit target as staged with its diff against the disk
docMarkdown = ''
if (tab === 'doc' && view) {
    const doc = guided.probe('org.moqui.devaide.DocServices.get#ArtifactDoc', {artifactId: 'entity:' + entityName})
    docMarkdown = doc.markdown || doc.refused || ''
}
targetText = editFile.text || ''
targetDiff = editFile.staged ? editFile.diff || '' : ''
targetPath = entity.edit ? entity.edit.path : ''
seedDiff = seedFile && seedFile.staged ? seedFile.diff || '' : ''
